window.BOOK={"key":"banatsuad","app":"mutoon-banatsuad","lsk":"mutoon_banatsuad_v1","prefix":"ba_","title":"بانت سعاد","sub":"الشعر العربي · كعب بن زهير رضي الله عنه (ت نحو ٢٦هـ) · ٥٨ بيتًا","poems":[{"id":"banatsuad","title":"بانت سعاد","nazim":"كعب بن زهير بن أبي سُلمى المزني رضي الله عنه","death":"ت نحو ٢٦هـ","meter":"البسيط","source":"جامع الكتب الإسلامية: شرح قصيدة كعب بن زهير «بانت سعاد» لابن هشام الأنصاري (نسخة مكتب الرحاب المقابلة المشكولة)","srcUrl":"https://ketabonline.com/ar/books/102440","note":"النص من القصيدة المسرودة أول شرح ابن هشام، قوبل كلمةً كلمةً بسكربت بشرح التبريزي ونص ويكي مصدر ونص الديوان (الموسوعة الشعرية) ورواية ابن إسحاق في البداية والنهاية، واعتُمد ما عليه أكثر الروايات المتداولة حيث اختلفت. أُكمل الشكل من التبريزي والديوان وويكي مصدر حيث اتفقت الكلمة، والتفصيل في تقرير المصادر.","verses":[["بَانَتْ سُعَادُ فَقَلْبِي الْيَوْمَ مَتْبُولُ","مُتَيَّمٌ إِثْرَهَا لَمْ يُفْدَ مَكْبُولُ"],["وَمَا سُعَادُ غَدَاةَ الْبَيْنِ إِذْ رَحَلُوا","إِلَّا أَغَنُّ غَضِيضُ الطَّرْفِ مَكْحُولُ"],["هَيْفَاءُ مُقْبِلَةً عَجْزَاءُ مُدْبِرَةً","لَا يُشْتَكَى قِصَرٌ مِنْهَا وَلَا طُولُ"],["تَجْلُو عَوَارِضَ ذِي ظَلْمٍ إِذَا ابْتَسَمَتْ","كَأَنَّهُ مُنْهَلٌ بالرَّاحِ مَعْلُولُ"],["شُجَّتْ بِذِي شَبَمٍ مِنْ مَاءِ مَحْنِيَةٍ","صَافٍ بِأَبْطَحَ أَضْحَى وهْوَ مَشْمُولُ"],["تَنْفِي الرِّيَاحُ الْقَذَى عَنْهُ وَأَفْرَطَهُ","مِنْ صَوْبِ سَارِيَةٍ بِيضٌ يَعَالِيلُ"],["أَكْرِمْ بِها خُلَّةً لَوْ أَنَّهَا صَدَقَتْ","مَوْعُودَها أَوْ لَوَ انَّ النُّصْحَ مَقْبُولُ"],["لَكِنَّهَا خُلَّةٌ قَدْ سِيطَ مِنْ دَمِهَا","فَجْعٌ وَوَلْعٌ وَإِخْلَافٌ وَتَبْدِيلُ"],["فَمَا تَدُومُ عَلَى حَالٍ تَكُونُ بِهَا","كَمَا تَلَوَّنُ فِي أَثْوَابِهَا الْغُولُ"],["ولا تَمَسَّكُ بالعَهْدِ الذِي زَعَمَتْ","إِلَّا كَمَا يُمْسِكُ الْمَاءَ الْغَرَابِيلُ"],["فلا يَغُرَّنْكَ ما مَنَّتْ وما وَعَدَتْ","إنَّ الأمانِيَّ والأحْلامَ تَضْليلُ"],["كَانَتْ مَوَاعِيدُ عُرْقُوبٍ لَهَا مَثَلًا","وَمَا مَوَاعِيدُهَا إِلَّا الْأَبَاطِيلُ"],["أَرْجُو وَآمُلُ أَنْ تَدْنُو مَوَدَّتُها","وَمَا إِخالُ لَدَيْنَا مِنْكِ تَنْويلُ"],["أَمْسَتْ سُعَادُ بِأَرْضٍ لَا يُبَلِّغُهَا","إِلَّا الْعِتَاقُ النَّجِيبَاتُ الْمَرَاسِيلُ"],["وَلَنْ يُبَلِّغَها إِلَّا عُذَافِرَةٌ","فِيهَا عَلَى الْأَيْنِ إِرْقَالٌ وَتَبْغِيلُ"],["مِنْ كُلِّ نَضَّاخَةِ الذِّفْرَى إِذَا عَرِقَتْ","عُرْضَتُهَا طَامِسُ الْأَعْلَامِ مَجْهُولُ"],["تَرْمِي الْغُيُوبَ بِعَيْنَيْ مُفْرِدٍ لَهِقٍ","إِذَا تَوَقَّدتِ الحُزَّانُ وَالْمِيلُ"],["ضَخْمٌ مُقَلَّدُهَا فَعْمٌ مُقَيَّدُهَا","فِي خَلْقِهَا عَنْ بَنَاتِ الْفَحْلِ تَفْضِيلُ"],["غَلْبَاءُ وَجْناءُ عُلكومٌ مُذَكَّرَةٌ","في دَفِّها سَعَةٌ قُدَّامُها مِيلُ"],["وجِلْدُها مِنْ أُطُومٍ ما يُؤَيِّسُهُ","طِلْحٌ بضَاحِيَةِ الْمَتْنَيْنِ مَهْزولُ"],["حَرْفٌ أَخُوهَا أَبُوهَا مِنْ مُهَجَّنَةٍ","وَعَمُّهَا خَالُهَا قَوْدَاءُ شِمْلِيلُ"],["يَمْشِي القُرادُ عَلَيْهَا ثُمَّ يُزْلِقُهُ","مِنْهَا لَبَانٌ وَأَقْرَابٌ زَهَالِيلُ"],["عَيْرَانَةٌ قُذِفَتْ بالنَّحْضِ عَنْ عُرُضٍ","مِرْفَقُهَا عَنْ بنَاتِ الزُّورِ مَفْتُولُ"],["كأنَّما فَاتَ عَيْنَيْهَا وَمَذْبَحَهَا","مِنْ خَطْمِهَا وَمِنْ اللَّحْيَيْنِ بِرْطِيلُ"],["تَمُرُّ مِثْلَ عَسِيبِ النَّخْلِ ذَا خُصَلٍ","فِي غَارِزٍ لَمْ تُخَوِّنْهُ الْأَحَالِيلُ"],["قَنْوَاءُ فِي حَرَّتَيْها لِلْبَصِيرِ بِهَا","عِتْقٌ مُبِينٌ وَفِي الْخَدَّيْنِ تَسْهِيلُ"],["تَخْدِي عَلَى يَسَرَاتٍ وَهْيَ لَاحِقَةٌ","ذَوَابِلٌ وَقْعُهُنَّ الأرْضَ تَحْلِيلُ"],["سُمْرُ الْعُجَايَاتِ يَتْرُكْنَ الْحَصَى زِيَمًا","لَمْ يَقِهِنَّ رُؤُوسَ الأُكْمِ تَنْعِيلُ"],["كَأَنَّ أَوْبَ ذِرَاعَيْهَا إذا عَرِقَتْ","وَقَدْ تَلَفَّعَ بالْقَوْرِ الْعَسَاقِيلُ"],["يَوْمًا يَظَلُّ بهِ الْحِرْباءُ مُصْطَخِدًا","كأنَّ ضَاحِيَهُ بالْشَّمْسِ مَمْلُولُ"],["وَقَالَ لِلْقَوْمِ حَادِيهِمْ وَقَدْ جَعَلَتْ","وُرْقُ الْجَنَادِبِ يَرْكُضْنَ الْحَصَا قِيلُوا"],["شَدَّ النَّهارِ ذِرَاعَا عَيْطَلٍ نَصَفٍ","قَامَتْ فَجَاوَبَهَا نُكْدٌ مَثَاكِيلُ"],["نَوَّاحَةٌ رَخْوَةُ الضَّبْعَيْنِ لَيْسَ لَهَا","لَمَّا نَعَى بِكْرَهَا النَّاعُونَ مَعْقُولُ"],["تَفْرِي اللَّبَانَ بِكَفَّيْهَا ومِدْرَعُها","مُشَقَّقٌ عَنْ تَرَاقِيهَا رَعَابِيلُ"],["يَسْعَى الْوُشَاةُ جَنَابَيْها وقَوْلُهُمُ","إِنَّكَ يَا ابْنَ أَبِي سُلْمَى لَمَقْتُولُ"],["وَقَالَ كلُّ خَلِيلٍ كُنْتُ آمُلُهُ","لَا أُلْهِيَنَّكَ إِنِّي عَنْكَ مَشْغُولُ"],["فَقُلْتُ خَلُّوا سَبيلِي لَا أَبَا لَكُمُ","فَكُلُّ مَا قَدَّرَ الرَّحْمَنُ مَفْعُولُ"],["كُلُّ ابْنِ أُنْثَى وَإِنْ طَالَتْ سَلَامَتُهُ","يَوْمًا عَلَى آلَةٍ حَدْبَاءَ مَحْمُولُ"],["أُنْبِئْتُ أَنَّ رَسُولَ اللَّهِ أَوْعَدَنِي","والعَفْوُ عِنْدَ رَسُولِ اللَّهِ مَأْمُولُ"],["مَهْلًا هَدَاكَ الذِي أَعْطَاكَ نَافِلَةَ","الْقُرْآنِ فِيهَا مَوَاعِيظٌ وَتَفْصِيلُ"],["لَا تَأْخُذَنِّي بِأَقْوَالِ الْوُشَاةِ وَلَمْ","أُذْنِبْ وإنْ كَثُرَتْ فِيَّ الْأَقَاوِيلُ"],["لَقَدْ أَقُومُ مَقَامًا لَوْ يَقُومُ بِهِ","أَرَى وَأَسْمَعُ مَا لَوْ يَسْمَعُ الْفِيلُ"],["لَظَلَّ يُرْعَدُ إِلَّا أَنْ يَكُونَ لَهُ","مِنَ الرَّسُولِ بِإِذْنِ اللَّهِ تَنْوِيلُ"],["حَتَّى وَضَعْتُ يَمِينِي لَا أُنَازِعُهُ","فِي كَفِّ ذِي نَقِمَاتٍ قِيلُهُ الْقِيلُ"],["لَذَاكَ أَهْيَبُ عِنْدِي إِذْ أُكَلِّمُهُ","وَقِيلَ إِنَّكَ مَنْسوبٌ وَمَسْؤُولُ"],["مِنْ خَادِرٍ مِنْ لُيُوثِ الْأُسْدِ مَسْكَنُهُ","مِنْ بَطْنِ عَثَّرَ غِيلٌ دُونَهُ غِيلُ"],["يَغْدُو فيُلْحِمُ ضُرْغَامَيْنِ عَيْشُهُمَا","لَحْمٌ مِنَ الْقَوْمِ مَعْفُورٌ خَرَاذِيلُ"],["إِذَا يُسَاوِرُ قِرْنًا لَا يَحِلُّ لَهُ","أَنْ يَتْرُكَ الْقِرْنَ إِلَّا وَهْوَ مَفْلُولُ"],["مِنْهُ تَظَلُّ سِباعُ الجَوِّ ضَامِزَةً","وَلَا تُمَشَّى بِوَادِيهِ الْأَرَاجِيلُ"],["وَلَا يَزَالُ بِوَادِيهِ أخُو ثِقَةٍ","مُطَرَّحُ الْبَزِّ والدِّرْسَانِ مَأْكُولُ"],["إِنَّ الرَّسُولَ لَسَيْفٌ يُسْتَضَاءُ بِهِ","مُهَنَّدٌ مِنْ سُيُوفِ اللَّهِ مَسْلُولُ"],["فِي عُصْبةٍ مِنْ قُرَيْشٍ قَالَ قَائِلُهُمْ","بِبَطْنِ مَكَّةَ لَمَّا أَسْلَمُوا زُولُوا"],["زَالُوا فمَا زَالَ أَنْكَاسٌ وَلَا كُشُفٌ","عِنْدَ اللِّقَاءِ وَلَا مِيلٌ مَعَازِيلُ"],["شُمُّ الْعَرانينِ أَبْطَالٌ لَبُوسُهُمُ","مِنْ نَسْجِ دَاوُدَ فِي الْهَيْجَا سَرَابِيلُ"],["بِيضٌ سَوَابِغُ قَدْ شُكَّتْ لَهَا حَلَقٌ","كأنَّها حَلَقُ الْقَفْعَاءِ مَجْدُولُ"],["لا يَفرَحونَ إذا نَالَتْ رِماحُهمُ","قومًا وليسوا مَجَازِيعًا إذا نِيلُوا"],["يَمْشُونَ مَشْيَ الْجِمَالِ الزُّهْرِ يَعْصِمُهُمْ","ضَرْبٌ إِذَا عَرَّدَ السُّودُ التَّنَابِيلُ"],["لَا يَقَعُ الطَّعْنُ إِلَّا فِي نُحُورِهِمُ","وما لَهُمْ عَنْ حِيَاضِ الْمَوْتِ تَهْلِيلُ"]],"secs":{"1":"بانت سعاد"}}],"sharh":false};
